func ptrTender(p unsafe.Pointer, c int32) any {
	r := (*tender.Tender)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 5:
		return (**string)(unsafe.Pointer(&r.RoutingGuideID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Mode))
	case 7:
		return (*string)(unsafe.Pointer(&r.Status))
	case 8:
		return &r.CurrentRank
	case 9:
		return &r.WorkflowID
	case 10:
		return (**string)(unsafe.Pointer(&r.CreatedByID))
	case 11:
		return (**string)(unsafe.Pointer(&r.CanceledByID))
	case 12:
		return &r.CancellationReason
	case 13:
		return (**string)(unsafe.Pointer(&r.AcceptedOfferID))
	case 14:
		return &r.AcceptedAt
	case 15:
		return &r.ExhaustedAt
	case 16:
		return &r.CanceledAt
	case 17:
		return &r.BounceCount
	case 18:
		return &r.LastBouncedAt
	case 19:
		return (**string)(unsafe.Pointer(&r.EscalatedFromID))
	case 20:
		return &r.EscalationRound
	case 21:
		return &r.Version
	case 22:
		return &r.CreatedAt
	case 23:
		return &r.UpdatedAt
	}
	return nil
}

func valueTender(p unsafe.Pointer, c int32) any {
	r := (*tender.Tender)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		if r.RoutingGuideID == nil {
			return nil
		}
		return string(*r.RoutingGuideID)
	case 6:
		return string(r.Mode)
	case 7:
		return string(r.Status)
	case 8:
		return r.CurrentRank
	case 9:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 10:
		if r.CreatedByID == nil {
			return nil
		}
		return string(*r.CreatedByID)
	case 11:
		if r.CanceledByID == nil {
			return nil
		}
		return string(*r.CanceledByID)
	case 12:
		if r.CancellationReason == "" {
			return nil
		}
		return r.CancellationReason
	case 13:
		if r.AcceptedOfferID == nil {
			return nil
		}
		return string(*r.AcceptedOfferID)
	case 14:
		if r.AcceptedAt == nil {
			return nil
		}
		return *r.AcceptedAt
	case 15:
		if r.ExhaustedAt == nil {
			return nil
		}
		return *r.ExhaustedAt
	case 16:
		if r.CanceledAt == nil {
			return nil
		}
		return *r.CanceledAt
	case 17:
		return r.BounceCount
	case 18:
		if r.LastBouncedAt == nil {
			return nil
		}
		return *r.LastBouncedAt
	case 19:
		if r.EscalatedFromID == nil {
			return nil
		}
		return string(*r.EscalatedFromID)
	case 20:
		return r.EscalationRound
	case 21:
		return r.Version
	case 22:
		return r.CreatedAt
	case 23:
		return r.UpdatedAt
	}
	return nil
}

func attachTender(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*tender.Tender)(p)
	switch rel {
	case 0:
		r.Shipment = (*shipment.Shipment)(child)
	case 1:
		r.ShipmentMove = (*shipment.ShipmentMove)(child)
	case 2:
		r.RoutingGuide = (*tender.RoutingGuide)(child)
	case 3:
		r.Offers = append(r.Offers, (*tender.TenderOffer)(child))
	}
}

